package com.bocsoft.sqleditor.execution;
import com.bocsoft.sqleditor.config.SqlEditorProperties;import com.bocsoft.sqleditor.datasource.RunningTaskCounter;import java.sql.Statement;import java.util.Map;import java.util.concurrent.ConcurrentHashMap;import java.util.concurrent.Semaphore;import java.util.concurrent.atomic.AtomicInteger;import org.springframework.stereotype.Component;
@Component public class ExecutionRegistry implements RunningTaskCounter {private final Map<String,Entry>entries=new ConcurrentHashMap<String,Entry>();private final Map<String,AtomicInteger>users=new ConcurrentHashMap<String,AtomicInteger>();private final Semaphore global;private final int perUser;public ExecutionRegistry(SqlEditorProperties p){global=new Semaphore(p.getExecution().getMaxConcurrentGlobal());perUser=p.getExecution().getMaxConcurrentPerUser();}
 public boolean contains(String id){return entries.containsKey(id);}public void acquire(String id,String user,String dataSource){AtomicInteger count=users.computeIfAbsent(user,k->new AtomicInteger());if(!global.tryAcquire())throw limit();int now=count.incrementAndGet();if(now>perUser){count.decrementAndGet();global.release();throw limit();}Entry e=new Entry(user,dataSource,Thread.currentThread());if(entries.putIfAbsent(id,e)!=null){releaseUser(user);throw conflict();}}
 public void bind(String id,Statement statement){Entry e=entries.get(id);if(e!=null)e.statement=statement;}public boolean cancel(String id,String user){Entry e=entries.get(id);if(e==null||!e.user.equals(user))return false;e.cancelled=true;try{if(e.statement!=null)e.statement.cancel();}catch(Exception ignored){}e.thread.interrupt();return true;}public boolean cancelled(String id){Entry e=entries.get(id);return e!=null&&e.cancelled;}public void finish(String id){Entry e=entries.remove(id);if(e!=null)releaseUser(e.user);}private void releaseUser(String user){AtomicInteger c=users.get(user);if(c!=null&&c.decrementAndGet()<=0)users.remove(user,c);global.release();}@Override public int count(String dataSourceId){int total=0;for(Entry e:entries.values())if(e.dataSource.equals(dataSourceId))total++;return total;}private RuntimeException limit(){return new com.bocsoft.sqleditor.common.ApiException(org.springframework.http.HttpStatus.TOO_MANY_REQUESTS,"EXECUTION_LIMIT_EXCEEDED","SQL 并发执行数量已达上限");}private RuntimeException conflict(){return new com.bocsoft.sqleditor.common.ApiException(org.springframework.http.HttpStatus.CONFLICT,"EXECUTION_ID_CONFLICT","执行 ID 已被使用");}private static class Entry{final String user,dataSource;final Thread thread;volatile Statement statement;volatile boolean cancelled;Entry(String u,String d,Thread t){user=u;dataSource=d;thread=t;}}}
